package main

import (
	"encoding/hex"

	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/p/onbloc/ibc/union/zkgm"
)

func main() {
	baseTokenHex := "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"
	imageHex := "b3df2bf46d34d2c15ec3d018dd29241a7ad980c5147a5bf580a9a836cc59f36e"
	destChannel := uint32(2)

	baseToken, err := hex.DecodeString(baseTokenHex)
	if err != nil {
		panic(err)
	}
	imageBytes, err := hex.DecodeString(imageHex)
	if err != nil {
		panic(err)
	}
	var image [32]byte
	copy(image[:], imageBytes)

	println(zkgm.PredictWrappedTokenV2(u256.Zero(), destChannel, baseToken, image))
}

