package main

import (
	"gno.land/p/nt/fqname/v0"
	"gno.land/r/demo/defi/grc20reg"
)

func main() {
	key := fqname.Construct("gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm/v1", "USDT2")
	println("key:", key)

	tok := grc20reg.Get(key)
	if tok == nil {
		println("grc20reg.Get: NOT FOUND (free)")
		return
	}
	println("grc20reg.Get: FOUND -> name=", tok.GetName(), "symbol=", tok.GetSymbol(), "decimals=", tok.GetDecimals())
}

