package main

import (
	"encoding/hex"

	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

func mustU256Hex(h string) *u256.Uint {
	b, err := hex.DecodeString(h)
	if err != nil {
		panic(err)
	}
	var arr [32]byte
	copy(arr[:], b)
	return u256.Zero().SetBytes32(arr[:])
}

func main(cur realm) {
	// 1. re-enable global rate limiting
	zkgm.SetRateLimitDisabled(cross(cur), false)

	// 2. new USDT2 bucket (same as old USDT)
	zkgm.SetBucketConfig(cross(cur),
		"ibc/fd333f0cb130c75f22211c49ba5fa506e5714f2c",
		u256.NewUint(100000000000),
		u256.NewUint(1000000),
	)

	// 3. new ETH bucket (same as old ETH: 100000000000000000000000 / 1000000000000000000)
	zkgm.SetBucketConfig(cross(cur),
		"ibc/8ac2058b042ac196234c2bd7875e43aec867de4a",
		mustU256Hex("00000000000000000000000000000000000000000000152d02c7e14af6800000"),
		u256.NewUint(1000000000000000000),
	)

	// 4. old USDT bucket -> effectively disabled (tokenbucket forbids literal 0)
	zkgm.SetBucketConfig(cross(cur),
		"ibc/8908315ff52040c1cb74d0573c5f9e58de598971",
		u256.NewUint(1),
		u256.NewUint(1),
	)

	// 5. old ETH bucket -> effectively disabled
	zkgm.SetBucketConfig(cross(cur),
		"ibc/8304388bbc79cdbb7557b156bb36c6c8517f12d9",
		u256.NewUint(1),
		u256.NewUint(1),
	)

	println("done")
}

